CREATE PROCEDURE SP_OrderStatus (@OrdID nvarchar(max),@FabID nvarchar(max),@CntID nvarchar(max),@ColID nvarchar(max),@Dt AS VARCHAR(30),@Dt1 AS VARCHAR(30))

AS

BEGIN 

-- KNITTING 

select distinct sum(Y.KnitDC) as KnitDC,sum(Y.KnitGrn) as KnitGrn,sum(Y.KnitMultiGrn) as KnitMultiGrn,sum(Y.KnitRet) as KnitRet,sum(Y.HeatDC) as HeatDC,sum(Y.HeatGrn) as HeatGrn,sum(Y.HeatMultiGrn) as HeatMultiGrn,sum(Y.HeatRet) as HeatRet,sum(Y.WashDC) as WashDC,sum(Y.WashGrn) as WashGrn,sum(Y.WashMultiGrn) as WashMultiGrn,sum(Y.WashRet) as WashRet,sum(Y.CompDC) as CompDC,sum(Y.CompGrn) as CompGrn,sum(Y.CompMultiGrn) as CompMultiGrn,sum(Y.CompRet) as CompRet from (select distinct sum(x.KnitDC) as KnitDC,sum(x.KnitGrn) as KnitGrn,sum(x.KnitMultiGrn) as KnitMultiGrn,sum(x.KnitRet) as KnitRet,0 as HeatDC,0 as HeatGrn,0 as HeatMultiGrn,0 as HeatRet,0 as WashDC,0 as WashGrn,0 as WashMultiGrn,0 as WashRet,0 as CompDC,0 as CompGrn,0 as CompMultiGrn,0 as CompRet from (select distinct Trs_Del3.OrdId,Trs_Del1.Prs_Dept as Dept,Trs_Del3.FabType AS FabID,Trs_Del3.Cnt AS CntID,Trs_Del3.Clr AS ColID,Trs_Del1.Dt,sum(Trs_Del3.Prog) as KnitDC,0 as  KnitGrn,0 as KnitMultiGrn,0 as KnitRet from Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN StockTable ON StockTable.OrdID = Trs_Del2.OrdId and Trs_Del2.StockID = StockTable.StockID INNER JOIN Trs_Del3 ON Trs_Del1.ID = Trs_Del3.ID  where  StockTable.YF='Y' and Trs_Del3.FabType=@FabID group by Trs_Del3.OrdId,Trs_Del1.Prs_Dept,Trs_Del3.FabType,Trs_Del3.Cnt,Trs_Del3.Clr,Trs_Del1.Dt UNION ALL select distinct Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt as Dt, 0 as KnitDC,sum(Trs_GRN2.RecKgs) as KnitGrn,0 as KnitMultiGrn,0 as KnitRet from Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN StockTable ON StockTable.StockID = Trs_GRN2.StockID  where GRNType='Process' and isnull(Trs_Grn1.External_GRNID,0)=0 and StockTable.FabID=@FabID group by Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt,StockTable.FabID UNION ALL select distinct Trs_MultiPrs_Grn3.ordid,Trs_MultiPrs_Grn3.DeptID,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_MultiPrs_Grn1.GRNDate as Dt, 0 as KnitDC,0 as KnitGrn,sum(Trs_MultiPrs_Grn3.RecKgs) as KnitMultiGrn,0 as KnitRet from Trs_MultiPrs_Grn1 INNER JOIN Trs_MultiPrs_Grn2 ON Trs_MultiPrs_Grn2.Id = Trs_MultiPrs_Grn1.Id LEFT OUTER JOIN Trs_MultiPrs_Grn3 ON Trs_MultiPrs_Grn3.ID = Trs_MultiPrs_Grn1.Id and Trs_MultiPrs_Grn3.DeptID = Trs_MultiPrs_Grn2.DeptID INNER JOIN StockTable ON StockTable.StockID = Trs_MultiPrs_Grn3.StockID group by Trs_MultiPrs_Grn3.ordid,Trs_MultiPrs_Grn3.DeptID,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_MultiPrs_Grn1.GRNDate,StockTable.FabID UNION ALL select distinct Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt as Dt,0 as KnitDC,0 as KnitGrn,0 as KnitMultiGrn,sum(Trs_GRN2.RecKgs) as KnitRet from Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN StockTable ON StockTable.StockID = Trs_GRN2.StockID where GRNType='Process Return' and StockTable.YF='Y' group by Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt,StockTable.FabID) X where x.OrdId=@OrdID and x.Dept in (4,43) and x.CntID=@CntID and X.ColID=@ColID and x.Dt>=@Dt and Dt<=@Dt1

--HEAT SETTING

UNION

select distinct 0 as KnitDC,0 as KnitGrn,0 as KnitMultiGrn,0 as KnitRet,sum(x.HeatDC) as HeatDC,sum(x.HeatGrn) as HeatGrn,sum(x.HeatMultiGrn) as HeatMultiGrn,sum(x.HeatRet) as HeatRet,0 as WashDC,0 as WashGrn,0 as WashMultiGrn,0 as WashRet,0 as CompDC,0 as CompGrn,0 as CompMultiGrn,0 as CompRet from (select distinct Trs_Del2.OrdId,Trs_Del1.Prs_Dept as Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Del1.Dt,sum(Trs_Del2.Kg) as HeatDC,0 as  HeatGrn,0 as HeatMultiGrn,0 as HeatRet from Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID  INNER JOIN StockTable ON StockTable.OrdID = Trs_Del2.OrdId and Trs_Del2.StockID = StockTable.StockID group by Trs_Del2.OrdId,Trs_Del1.Prs_Dept,StockTable.CntID,StockTable.ColID,Trs_Del1.Dt,StockTable.FabID UNION ALL select distinct Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt as Dt, 0 as HeatDC,sum(Trs_GRN2.RecKgs) as HeatGrn,0 as HeatMultiGrn,0 as HeatRet from Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN StockTable ON StockTable.StockID = Trs_GRN2.StockID  where GRNType='Process' and isnull(Trs_Grn1.External_GRNID,0)=0 group by Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt,StockTable.FabID UNION ALL select distinct Trs_MultiPrs_Grn3.ordid,Trs_MultiPrs_Grn3.DeptID,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_MultiPrs_Grn1.GRNDate as Dt, 0 as HeatDC,0 as HeatGrn,sum(Trs_MultiPrs_Grn3.RecKgs) as HeatMultiGrn,0 as HeatRet from Trs_MultiPrs_Grn1 INNER JOIN Trs_MultiPrs_Grn2 ON Trs_MultiPrs_Grn2.Id = Trs_MultiPrs_Grn1.Id LEFT OUTER JOIN Trs_MultiPrs_Grn3 ON Trs_MultiPrs_Grn3.ID = Trs_MultiPrs_Grn1.Id and Trs_MultiPrs_Grn3.DeptID = Trs_MultiPrs_Grn2.DeptID INNER JOIN StockTable ON StockTable.StockID = Trs_MultiPrs_Grn3.StockID group by Trs_MultiPrs_Grn3.ordid,Trs_MultiPrs_Grn3.DeptID,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_MultiPrs_Grn1.GRNDate UNION ALL select distinct Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt as Dt,0 as HeatDC,0 as HeatGrn,0 as HeatMultiGrn,sum(Trs_GRN2.RecKgs) as HeatRet from Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN StockTable ON StockTable.StockID = Trs_GRN2.StockID where GRNType='Process Return' group by Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt,StockTable.FabID) X where x.OrdId=@OrdID and x.Dept in (5) and x.FabID=@FabID and x.CntID=@CntID and X.ColID=@ColID and x.Dt>=@Dt and Dt<=@Dt1


-- WASIHNG

UNION

select distinct 0 as KnitDC,0 as KnitGrn,0 as KnitMultiGrn,0 as KnitRet,0 as HeatDC,0 as HeatGrn,0 as HeatMultiGrn,0 as HeatRet,sum(x.WashDC) as WashDC,sum(x.WashGrn) as WashGrn,sum(x.WashMultiGrn) as WashMultiGrn,sum(x.WashRet) as WashRet,0 as CompDC,0 as CompGrn,0 as CompMultiGrn,0 as CompRet from (select distinct Trs_Del2.OrdId,Trs_Del1.Prs_Dept as Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Del1.Dt,sum(Trs_Del2.Kg) as WashDC,0 as  WashGrn,0 as WashMultiGrn,0 as WashRet from Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID  INNER JOIN StockTable ON StockTable.OrdID = Trs_Del2.OrdId and Trs_Del2.StockID = StockTable.StockID group by Trs_Del2.OrdId,Trs_Del1.Prs_Dept,StockTable.CntID,StockTable.ColID,Trs_Del1.Dt,StockTable.FabID UNION ALL select distinct Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt as Dt, 0 as WashDC,sum(Trs_GRN2.RecKgs) as WashGrn,0 as WashMultiGrn,0 as WashRet from Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN StockTable ON StockTable.StockID = Trs_GRN2.StockID  where GRNType='Process' and isnull(Trs_Grn1.External_GRNID,0)=0 group by Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt,StockTable.FabID UNION ALL select distinct Trs_MultiPrs_Grn3.ordid,Trs_MultiPrs_Grn3.DeptID,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_MultiPrs_Grn1.GRNDate as Dt, 0 as WashDC,0 as WashGrn,sum(Trs_MultiPrs_Grn3.RecKgs) as WashMultiGrn,0 as WashRet from Trs_MultiPrs_Grn1 INNER JOIN Trs_MultiPrs_Grn2 ON Trs_MultiPrs_Grn2.Id = Trs_MultiPrs_Grn1.Id LEFT OUTER JOIN Trs_MultiPrs_Grn3 ON Trs_MultiPrs_Grn3.ID = Trs_MultiPrs_Grn1.Id and Trs_MultiPrs_Grn3.DeptID = Trs_MultiPrs_Grn2.DeptID INNER JOIN StockTable ON StockTable.StockID = Trs_MultiPrs_Grn3.StockID group by Trs_MultiPrs_Grn3.ordid,Trs_MultiPrs_Grn3.DeptID,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_MultiPrs_Grn1.GRNDate UNION ALL select distinct Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt as Dt,0 as WashDC,0 as WashGrn,0 as WashMultiGrn,sum(Trs_GRN2.RecKgs) as WashRet from Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN StockTable ON StockTable.StockID = Trs_GRN2.StockID where GRNType='Process Return' group by Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt,StockTable.FabID) X where x.OrdId=@OrdID and x.Dept in (7,19,41,42) and x.FabID=@FabID and x.CntID=@CntID and X.ColID=@ColID and x.Dt>=@Dt and Dt<=@Dt1

--COMPACTING

UNION

select distinct 0 as KnitDC,0 as KnitGrn,0 as KnitMultiGrn,0 as KnitRet,0 as HeatDC,0 as HeatGrn,0 as HeatMultiGrn,0 as HeatRet,0 as WashDC,0 as WashGrn,0 as WashMultiGrn,0 as WashRet,sum(x.CompDC) as CompDC,sum(x.CompGrn) as CompGrn,sum(x.CompMultiGrn) as CompMultiGrn,sum(x.CompRet) as CompRet from (select distinct Trs_Del2.OrdId,Trs_Del1.Prs_Dept as Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Del1.Dt,sum(Trs_Del2.Kg) as CompDC,0 as CompGrn,0 as CompMultiGrn,0 as CompRet from Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID  INNER JOIN StockTable ON StockTable.OrdID = Trs_Del2.OrdId and Trs_Del2.StockID = StockTable.StockID group by Trs_Del2.OrdId,Trs_Del1.Prs_Dept,StockTable.CntID,StockTable.ColID,Trs_Del1.Dt,StockTable.FabID UNION ALL select distinct Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt as Dt, 0 as CompDC,sum(Trs_GRN2.RecKgs) as CompGrn,0 as CompMultiGrn,0 as CompRet from Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN StockTable ON StockTable.StockID = Trs_GRN2.StockID  where GRNType='Process' and isnull(Trs_Grn1.External_GRNID,0)=0 group by Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt,StockTable.FabID UNION ALL select distinct Trs_MultiPrs_Grn3.ordid,Trs_MultiPrs_Grn3.DeptID,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_MultiPrs_Grn1.GRNDate as Dt, 0 as CompDC,0 as CompGrn,sum(Trs_MultiPrs_Grn3.RecKgs) as CompMultiGrn,0 as CompRet from Trs_MultiPrs_Grn1 INNER JOIN Trs_MultiPrs_Grn2 ON Trs_MultiPrs_Grn2.Id = Trs_MultiPrs_Grn1.Id LEFT OUTER JOIN Trs_MultiPrs_Grn3 ON Trs_MultiPrs_Grn3.ID = Trs_MultiPrs_Grn1.Id and Trs_MultiPrs_Grn3.DeptID = Trs_MultiPrs_Grn2.DeptID INNER JOIN StockTable ON StockTable.StockID = Trs_MultiPrs_Grn3.StockID group by Trs_MultiPrs_Grn3.ordid,Trs_MultiPrs_Grn3.DeptID,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_MultiPrs_Grn1.GRNDate UNION ALL select distinct Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.FabID,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt as Dt,0 as CompDC,0 as CompGrn,0 as CompMultiGrn,sum(Trs_GRN2.RecKgs) as CompRet from Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN StockTable ON StockTable.StockID = Trs_GRN2.StockID where GRNType='Process Return' group by Trs_GRN2.ordid,Trs_Grn1.Dept,StockTable.CntID,StockTable.ColID,Trs_Grn1.dt,StockTable.FabID) X where x.OrdId=@OrdID and x.Dept in (9,18,28,40,44,45,46) and x.FabID=@FabID and x.CntID=@CntID and X.ColID=@ColID and x.Dt>=@Dt and Dt<=@Dt1) Y

END








